Here’s a practical way to make translation API calls low-latency and efficient, based on what we discussed earlier about DeepL vs Google and your Node.js/Express setup.

Key principles for fast translations
- Avoid extra hops: let the provider auto-detect source language (both DeepL and Google support this) instead of calling a separate detection service.
- Batch whenever possible: send multiple texts in one request to amortize connection/TLS overhead.
- Cache aggressively: use a two-tier cache (in-memory LRU for hot hits + Redis for cross-instance sharing).
- Deduplicate in-flight requests: if the same text/target is requested concurrently, do one upstream call and fan out the result.
- Reuse connections: enable HTTP keep-alive and short timeouts.
- Retry sanely: exponential backoff on 429/5xx and respect Retry-After.
- Observe and cap concurrency: small pool to avoid provider throttling; measure p50/p95/p99.

Node 18 + Express example (DeepL REST, batching, keep‑alive, 2‑tier cache, in‑flight dedupe, retries)
```javascript
// npm i express axios lru-cache redis
const express = require('express');
const axios = require('axios');
const { URLSearchParams } = require('url');
const { createClient } = require('redis');
const LRU = require('lru-cache');
const https = require('https');

const app = express();
app.use(express.json());

// Config
const DEEPL_API_KEY = process.env.DEEPL_API_KEY; // set in env
const DEEPL_URL = 'https://api.deepl.com/v2/translate'; // or https://api-free.deepl.com/v2/translate
const TIMEOUT_MS = 3000;
const CACHE_TTL_SEC = 3600;

// Axios instance with keep-alive + sane defaults
const http = axios.create({
  baseURL: DEEPL_URL,
  timeout: TIMEOUT_MS,
  httpsAgent: new https.Agent({ keepAlive: true, maxSockets: 100 }),
  decompress: true,
  validateStatus: s => s >= 200 && s < 500
});

// 2-tier cache
const memoryCache = new LRU({ max: 2000, ttl: CACHE_TTL_SEC * 1000 });
const redis = createClient({ url: process.env.REDIS_URL || 'redis://localhost:6379' });
redis.connect();

// Deduplicate identical concurrent calls
const inFlight = new Map(); // key -> Promise

function cacheKey(text, sourceLang, targetLang) {
  const norm = (s) => (s || '').trim();
  return `deepl:${norm(sourceLang)}:${norm(targetLang)}:${norm(text)}`;
}

async function getCached(key) {
  const mem = memoryCache.get(key);
  if (mem !== undefined) return mem;
  const r = await redis.get(key);
  if (r) {
    const parsed = JSON.parse(r);
    memoryCache.set(key, parsed);
    return parsed;
  }
  return undefined;
}

async function setCached(key, value) {
  memoryCache.set(key, value);
  await redis.setEx(key, CACHE_TTL_SEC, JSON.stringify(value));
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function deeplTranslateBatch(texts, sourceLang, targetLang) {
  // Exponential backoff up to ~8s total
  let delay = 500;
  for (let attempt = 0; attempt < 4; attempt++) {
    const params = new URLSearchParams();
    texts.forEach(t => params.append('text', t));
    if (sourceLang) params.append('source_lang', sourceLang); // omit to auto-detect
    params.append('target_lang', targetLang);

    const resp = await http.post('', params, {
      headers: { 'Authorization': `DeepL-Auth-Key ${DEEPL_API_KEY}` }
    });

    if (resp.status >= 200 && resp.status < 300) {
      return resp.data.translations.map(t => t.text);
    }

    if (resp.status === 429 || resp.status >= 500) {
      const ra = parseInt(resp.headers['retry-after'] || '0', 10);
      await sleep(ra ? ra * 1000 : delay);
      delay = Math.min(delay * 2, 4000);
      continue;
    }

    throw new Error(`DeepL error ${resp.status}: ${JSON.stringify(resp.data)}`);
  }
  throw new Error('DeepL retries exhausted');
}

async function translateTexts(texts, sourceLang, targetLang) {
  const results = new Array(texts.length);
  const missIndices = [];
  const missTexts = [];
  const missKeys = [];

  // Check caches
  for (let i = 0; i < texts.length; i++) {
    const key = cacheKey(texts[i], sourceLang, targetLang);
    // Dedup in-flight
    if (inFlight.has(key)) {
      results[i] = await inFlight.get(key);
      continue;
    }
    const cached = await getCached(key);
    if (cached !== undefined) {
      results[i] = cached;
    } else {
      missIndices.push(i);
      missTexts.push(texts[i]);
      missKeys.push(key);
    }
  }

  if (missTexts.length === 0) return results;

  // Single in-flight promise per unique batch signature to dedupe
  const batchKey = `batch:${targetLang}:${sourceLang || 'auto'}:${missTexts.join('|')}`;
  let batchPromise = inFlight.get(batchKey);
  if (!batchPromise) {
    batchPromise = (async () => {
      const translated = await deeplTranslateBatch(missTexts, sourceLang, targetLang);
      // Populate caches for misses
      await Promise.all(translated.map((tr, idx) => setCached(missKeys[idx], tr)));
      return translated;
    })().finally(() => {
      inFlight.delete(batchKey);
    });
    inFlight.set(batchKey, batchPromise);
  }

  const translated = await batchPromise;
  missIndices.forEach((idx, j) => { results[idx] = translated[j]; });
  return results;
}

app.post('/translate', async (req, res) => {
  try {
    const { text, texts, targetLang, sourceLang } = req.body || {};
    if (!targetLang || (!text && !Array.isArray(texts))) {
      return res.status(400).json({ error: 'Provide targetLang and text (string) or texts (array)' });
    }

    const list = Array.isArray(texts) ? texts : [text];
    const out = await translateTexts(list, sourceLang, targetLang);

    return res.json(Array.isArray(texts) ? { translations: out } : { translatedText: out[0] });
  } catch (e) {
    return res.status(502).json({ error: 'Translation failed', detail: String(e.message || e) });
  }
});

app.listen(4500, () => console.log('Translation service on 4500'));
```

Why this is fast
- Auto-detect avoids a separate language-detection call.
- Batch mode sends multiple texts in one request.
- Keep-alive avoids repeated TCP/TLS handshakes.
- LRU + Redis deliver hot results in sub-milliseconds and share cache across instances.
- In-flight dedupe prevents stampedes on identical inputs.
- Backoff/Retry handles transient 429/5xx without user-facing failures.

If you prefer Google Cloud Translate v3
- Use the @google-cloud/translate v3 client and pass multiple contents in one TranslateText call.
- Place your service in the same region as Google’s endpoint for lower latency.
- The same caching/dedupe/retry patterns apply.

Extra low-latency tips
- Co-locate your service with the provider’s region and your users if possible.
- Use short HTTP timeouts and a small concurrency pool to avoid queue buildup.
- Normalize inputs for better cache hits (trim whitespace, collapse spaces, consistent casing if acceptable).
- Chunk very long texts to stay within provider limits, then reassemble.

